import { Scene, Color } from "retiam";
import { Star, Gear2D, Cross, CurvedArrow } from "retiam/shapes";

export class Technical2DScene extends Scene {
    public async run() {
        // 1. Star with rounded outer tips
        const star = new Star({ points: 6, outerRadius: 1.5, innerRadius: 0.8, cornerRadius: 0.12 });
        star.paint.fill = new Color(1.0, 0.7, 0.2, 0.35);
        star.paint.stroke = new Color(1.0, 0.8, 0.3, 1.0);
        star.paint.stroke_width = 0.05;
        star.move([-4, 0, 0]);
        this.add(star);

        // 2. Mechanical Gear with center bore
        const gear = new Gear2D({ teeth: 12, outerRadius: 1.4, rootRadius: 1.0, boreRadius: 0.35 });
        gear.paint.fill = new Color(0.3, 0.6, 1.0, 0.35);
        gear.paint.stroke = new Color(0.4, 0.7, 1.0, 1.0);
        gear.paint.stroke_width = 0.05;
        gear.move([0, 0, 0]);
        this.add(gear);

        // 3. Sweeping Indicator Arrow
        const arrow = new CurvedArrow({ radius: 1.8, startAngle: 0, endAngle: Math.PI * 0.75, headLength: 0.4 });
        arrow.paint.fill = new Color(0.9, 0.3, 0.4, 1.0);
        arrow.paint.stroke = new Color(1.0, 0.4, 0.5, 1.0);
        arrow.paint.stroke_width = 0.08;
        arrow.move([4, 0, 0]);
        this.add(arrow);

        // Live rotation in update loop
        this.always((_t, dt) => {
            gear.transform.rotateWorldZ(dt * 0.001);
            star.transform.rotateWorldZ(-dt * 0.0005);
        });
    }
}

import { Scene, Color, OrbitCameraController } from "retiam";
import { Dodecahedron, TorusKnot3D, Capsule3D, Helix3D } from "retiam/shapes";

export class Polyhedra3DScene extends Scene {
    public async run() {
        this.camera.position.set([0, 0, 15]);
        new OrbitCameraController(this, this.camera);

        // 1. Crystal Dodecahedron (PBR Metallic with Flat Facet Normals)
        const dodeca = new Dodecahedron(1.2);
        dodeca.material.color = new Color(0.65, 0.35, 0.95, 1.0); // Royal Amethyst
        dodeca.material.metallic = 0.85;
        dodeca.material.roughness = 0.2;
        dodeca.move([-4, 1.5, 0]);
        this.add(dodeca);

        // 2. Smooth Torus Knot (Parallel Transport Tube)
        const knot = new TorusKnot3D({ radius: 1.1, tubeRadius: 0.22, p: 2, q: 3 });
        knot.material.color = new Color(0.95, 0.6, 0.15, 1.0); // Gold
        knot.material.metallic = 0.9;
        knot.material.roughness = 0.15;
        knot.move([4, 1.5, 0]);
        this.add(knot);

        // 3. Helical Spring
        const spring = new Helix3D({ radius: 0.8, pitch: 0.5, turns: 4, tubeRadius: 0.1 });
        spring.material.color = new Color(0.2, 0.8, 1.0, 1.0); // Cyan Steel
        spring.material.metallic = 0.8;
        spring.material.roughness = 0.25;
        spring.move([-4, -2.5, 0]);
        this.add(spring);

        // 4. Capsule Pill
        const cap = new Capsule3D({ radius: 0.6, length: 1.4 });
        cap.material.color = new Color(0.2, 0.9, 0.5, 1.0); // Emerald
        cap.material.metallic = 0.7;
        cap.material.roughness = 0.3;
        cap.move([4, -2.5, 0]);
        this.add(cap);

        // Continuous tumbling rotations
        this.always((_t, dt) => {
            const rot = dt * 0.001;
            dodeca.transform.rotateWorldY(rot);
            dodeca.transform.rotateWorldX(rot * 0.5);

            knot.transform.rotateWorldY(rot * 1.2);
            knot.transform.rotateWorldZ(rot * 0.6);

            spring.transform.rotateWorldY(rot * 1.5);
            cap.transform.rotateWorldX(rot * 0.8);
        });
    }
}
